)

INSERT INTO order_items (
    order_id, product_id, product_name, cover_url, unit_price,
    quantity, subtotal
)
VALUES (
    #{orderId}, #{productId}, #{productName}, #{coverUrl}, #{unitPrice},
    #{quantity}, #{subtotal}
)

